import json
root=Path('dist');root.mkdir(exist_ok=True)
(root/'versions.json').write_text(json.dumps({'latest':'v2','versions':[{'id':'v2','date':'2026-09-30','title':'A broader perspective','path':'/versions/v2/','changes':'/changes/v1-v2/'},{'id':'v1','date':'2025-11-02','title':'The starting point','path':'/versions/v1/','dateSource':'Last content commit, America/Sao_Paulo'}]},indent=2))
css='''@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--paper:#f5f4ef;--ink:#173a35;--muted:#687872;--line:#d9ded6;--accent:#dc6945}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}button{font:inherit;cursor:pointer}a:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:5px}.layout{margin-right:264px}.nav{height:95px;border-bottom:1px solid var(--line);margin:0 6%;display:flex;align-items:center;justify-content:space-between}.brand{font-family:'Space Grotesk',sans-serif;font-size:24px;font-weight:600;letter-spacing:-1px}.brand b{color:var(--accent)}.nav-links{display:flex;gap:28px;font-size:13px}.hero{padding:78px 6% 65px;position:relative;overflow:hidden}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;font-weight:700;display:flex;align-items:center;gap:10px}.dot{height:7px;width:7px;background:var(--accent);border-radius:50%}h1,h2,h3{font-family:'Space Grotesk',sans-serif;font-weight:500}h1{font-size:clamp(48px,6vw,86px);letter-spacing:-5px;line-height:1.04;margin:30px 0}h1 em{font-style:normal;color:var(--accent)}.intro{font-size:17px;line-height:1.8;max-width:510px;color:var(--muted)}.actions{display:flex;gap:22px;align-items:center;margin-top:28px;font-size:13px}.button{background:var(--ink);color:white;padding:15px 22px;border-radius:3px;display:inline-block}.meta{display:flex;gap:25px;font-size:11px;letter-spacing:1px;color:var(--muted);margin-top:48px}.orbit{position:absolute;right:5%;top:95px;width:190px;height:190px;border:1px solid var(--line);border-radius:50%;z-index:-0;opacity:.8}.orbit:before,.orbit:after{content:'';position:absolute;inset:22px;border:1px solid var(--line);border-radius:50%}.orbit:after{inset:49px;border-color:var(--accent)}.hero-content{position:relative;z-index:1}.section{padding:50px 6%;border-top:1px solid var(--line)}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:30px}.section h2{font-size:31px;letter-spacing:-1px;margin:0}.section-number{font-size:11px;color:var(--accent);margin-right:16px}.section p{color:var(--muted);font-size:15px;line-height:1.85}.columns{display:grid;grid-template-columns:1.2fr 1fr;gap:50px}.section h3{font-size:19px;margin-top:0}.skills{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}.skills span{border:1px solid var(--line);padding:8px 12px;border-radius:3px;font-size:12px}.project{display:grid;grid-template-columns:40px 1fr 30px;gap:15px;padding:25px 0;border-top:1px solid var(--line)}.project h3{margin:0 0 7px}.project p{margin:0}.project small{color:var(--muted)}.project-num{color:var(--accent);font-size:12px;padding-top:5px}.cloud{background:#e9eee6}.footer{padding:50px 6%;background:var(--ink);color:var(--paper)}.footer h2{font-size:42px;margin:0 0 25px}.footer-links{display:flex;gap:25px;font-size:13px}.footnote{margin-top:45px;font-size:11px;opacity:.7;display:flex;justify-content:space-between}.timeline{position:fixed;right:0;top:0;width:264px;height:100vh;border-left:1px solid var(--line);background:#eeeee7;padding:38px 28px;z-index:10}.timeline-title{font-size:11px;text-transform:uppercase;letter-spacing:2px;margin:0 0 14px}.timeline-description{font-size:12px;color:var(--muted);line-height:1.7}.timeline-list{list-style:none;padding:0;margin:45px 0 0 7px;border-left:1px solid #c7cec4}.timeline-item{padding:0 0 38px 20px;position:relative}.timeline-item:before{content:'';position:absolute;left:-5px;top:4px;width:9px;height:9px;background:#c7cec4;border:2px solid #eeeee7;border-radius:50%}.timeline-item.active:before{background:var(--accent);box-shadow:0 0 0 3px #eed9cb}.timeline-item time{font-size:10px;color:var(--muted);letter-spacing:1px}.timeline-item h3{font-size:15px;margin:12px 0}.timeline-item a{font-size:11px;display:block;margin-top:12px}.timeline-item .pill{display:inline-block;color:var(--accent);font-size:9px;letter-spacing:1px;text-transform:uppercase;margin-top:9px}.timeline-bottom{position:absolute;bottom:30px;font-size:11px;color:var(--muted);line-height:1.8}.history-toggle{display:none}.archive-bar{padding:18px 6%;font-size:12px;background:#e9eee6;border-bottom:1px solid var(--line)}iframe.archive{border:0;width:100%;height:calc(100vh - 54px);display:block}.diff-title{font-size:65px}.diff-label{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--accent)}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px}.compare-card{padding:25px;background:#eceee7;border:1px solid var(--line)}.compare-card.after{background:#e4ece1}.compare-card h3{margin:18px 0}.compare-card p{margin:0}.removed{background:#f2dfd7;padding:2px 4px;text-decoration:line-through}.added{background:#d5e5d1;padding:2px 4px}.mini-v1{border-radius:8px;background:linear-gradient(135deg,#e2e8f0,#dbeafe);padding:25px;text-align:center;color:#0f172a}.mini-v1 div{padding:20px;background:white;border-radius:8px;margin-top:12px}.mini-v2{background:var(--paper);padding:25px;border-left:5px solid var(--accent);font-family:'Space Grotesk',sans-serif;font-size:30px}.motion{animation:enter .5s ease both}@keyframes enter{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}@media(min-width:1500px){.layout{max-width:1200px;margin-left:auto;margin-right:264px}.orbit{right:12%}}@media(max-width:1100px){.orbit{display:none}h1{letter-spacing:-3px}.columns{gap:25px}}@media(max-width:760px){.layout{margin-right:0}.timeline{display:none;width:264px;box-shadow:-10px 0 40px #173a3520}.timeline.open{display:block}.history-toggle{display:block;position:fixed;bottom:20px;right:20px;border:0;border-radius:30px;padding:13px 19px;background:var(--ink);color:white;z-index:20;box-shadow:0 4px 20px #173a3530}.nav{height:76px}.nav-links{gap:16px}.nav-links a:first-child{display:none}.hero{padding-top:55px}h1{font-size:55px}.columns,.comparison{grid-template-columns:1fr}.meta{flex-wrap:wrap}.footer-links{flex-wrap:wrap}.footnote{gap:20px;padding-bottom:45px}.diff-title{font-size:47px}.section{padding-top:36px;padding-bottom:36px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}'''
(root/'style.css').write_text(css)
(root/'timeline.js').write_text('''const path=location.pathname;const version=path.includes('/v1/')?'v1':'v2';fetch('/versions.json').then(r=>{if(!r.ok)throw Error('catalog');return r.json()}).then(data=>{const list=document.querySelector('.timeline-list');data.versions.forEach(item=>{const li=document.createElement('li');li.className='timeline-item'+(item.id===version&&!path.includes('/changes/')?' active':'');const date=document.createElement('time');date.dateTime=item.date;date.textContent=new Date(item.date+'T12:00:00').toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'});li.append(date);const title=document.createElement('h3');title.textContent=item.title;li.append(title);if(item.id===data.latest){const p=document.createElement('span');p.className='pill';p.textContent='Latest version';li.append(p)}const a=document.createElement('a');a.href=item.path;a.textContent='View '+item.id+' ↗';if(item.id===version&&!path.includes('/changes/'))a.setAttribute('aria-current','page');li.append(a);if(item.changes){const c=document.createElement('a');c.href=item.changes;c.textContent='See what changed →';if(path===item.changes)c.setAttribute('aria-current','page');li.append(c)}if(item.dateSource)date.title=item.dateSource;list.append(li)})}).catch(()=>{document.querySelector('.timeline-list').textContent='History could not load. Please refresh.'});const toggle=document.querySelector('.history-toggle');toggle.addEventListener('click',()=>{const open=document.querySelector('.timeline').classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Close history ×':'History ↗'});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.timeline').classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent='History ↗'}});''')
def shell(content,title):
 return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Filipe's personal portfolio: software, data, cloud and a timeline of what changes."><title>{title} · Filipe</title><link rel="stylesheet" href="/style.css"></head><body><div class="layout">{content}</div><aside class="timeline" id="history" aria-label="Version history"><h2 class="timeline-title">A work in progress</h2><p class="timeline-description">Different chapters. Same curiosity.<br>Explore this site through time.</p><ol class="timeline-list"></ol><div class="timeline-bottom">Each version is a snapshot.<br><a href="/">Back to the present ↗</a></div></aside><button class="history-toggle" aria-controls="history" aria-expanded="false">History ↗</button><script src="/timeline.js" defer></script></body></html>'''
nav='''<nav class="nav" aria-label="Main navigation"><a class="brand" href="/">filipe<b>.</b></a><div class="nav-links"><a href="/#about">About</a><a href="/#projects">Projects</a><a href="/#contact">Let's talk ↗</a></div></nav>'''
footer='''<footer class="footer" id="contact"><div class="eyebrow">Have something in mind?</div><h2>Let's build something useful.</h2><div class="footer-links"><a href="mailto:filipeee0@gmail.com">Email ↗</a><a href="https://github.com/Filipe-Araujo0">GitHub ↗</a><a href="https://www.linkedin.com/in/filipe-da-silva-araujo-08763916a/">LinkedIn ↗</a></div><div class="footnote"><span>Filipe · São Paulo, Brazil</span><a href="https://github.com/Filipe-Araujo0/aboutMe">Explore the source code ↗</a></div></footer>'''
latest=nav+'''<main class="motion"><section class="hero"><div class="orbit" aria-hidden="true"></div><div class="hero-content"><div class="eyebrow"><span class="dot"></span>Software · Data · Curiosity</div><h1>Make it work.<br>Make it <em>matter.</em></h1><p class="intro">I'm Filipe. I build software that turns messy data and everyday processes into useful tools.</p><div class="actions"><a class="button" href="#projects">Explore my work ↗</a><a href="#about">A little about me ↓</a></div><div class="meta"><span>BASED IN SÃO PAULO, BR</span><span>VERSION 02 / SEPTEMBER 2026</span></div></div></section><section class="section" id="about"><div class="section-head"><h2><span class="section-number">01</span>Curiosity, put to work.</h2></div><div class="columns"><div><p>My background is in mathematics and statistics. Programming started with web scraping and automations, then grew into data pipelines and web systems that help people work with information.</p><p>I enjoy connecting the pieces: collecting data, making it useful, and building an interface that makes a complex process easier to use.</p></div><div><h3>From internal tools to bigger ideas.</h3><p>Much of my work has been about improving internal processes, adding control and monitoring, and supporting business analysts. My ambition is to build a technology solution that grows beyond a company's internal operations.</p></div></div></section><section class="section"><div class="section-head"><h2><span class="section-number">02</span>Tools for the job.</h2><span class="eyebrow">Always learning</span></div><div class="columns"><div><h3>Software & data</h3><p>Python is my starting point. APIs, relational databases, concurrency and Linux are part of the foundation.</p><div class="skills">'''+''.join('<span>'+x+'</span>' for x in ['Python','Django','FastAPI','Pandas','HTTPX','Asyncio','Pydantic','SQL'])+'''</div></div><div><h3>Interfaces & operations</h3><p>From Django templates and HTMX to modern frontend tools, with cloud services and business tooling alongside them.</p><div class="skills">'''+''.join('<span>'+x+'</span>' for x in ['React','TypeScript','Tailwind','Vite','S3','Azure Storage','Power BI','Power Automate'])+'''</div></div></div></section><section class="section" id="projects"><div class="section-head"><h2><span class="section-number">03</span>Out in the open.</h2><a href="https://github.com/Filipe-Araujo0" style="font-size:12px">All repositories ↗</a></div><a class="project" href="https://github.com/Filipe-Araujo0/aboutMe"><span class="project-num">01</span><div><h3>This evolving portfolio</h3><p>A personal site that keeps its past accessible. Separate snapshots, a timeline, and an editorial look at what changed.</p><small>Frontend · Version history · Open source</small></div><span>↗</span></a><a class="project" href="https://github.com/Filipe-Araujo0?tab=repositories"><span class="project-num">02</span><div><h3>More code, more experiments</h3><p>Explore my public repositories on GitHub.</p><small>Projects & experiments</small></div><span>↗</span></a></section><section class="section cloud"><div class="section-head"><h2><span class="section-number">04</span>Thinking at a different scale.</h2></div><div class="columns"><p>Cloud interests me for the practical things it makes possible in everyday work, and for the architecture behind it: how systems reach the efficiency needed to support computing at a much larger scale.</p><div><h3>A continuing learning process.</h3><p>I like keeping my thoughts and plans organized, using tools such as Todoist, Obsidian and simple documents. This site is another way to keep that process visible, one chapter at a time.</p><a href="/changes/v1-v2/" style="font-size:13px">Read the latest chapter →</a></div></div></section></main>'''+footer
(root/'index.html').write_text(shell(latest,'Software, data & curiosity'))
for version in ['v2']:
 d=root/'versions'/version;d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(shell(latest,'Version 02'))
d=root/'versions/v1';d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(shell('''<div class="archive-bar">ARCHIVE / V01 · November 2, 2025 · Date based on the content commit <a href="/changes/v1-v2/" style="float:right">See what changed →</a></div><iframe class="archive" title="Original portfolio, version 1" src="/archive/v1/"></iframe>''','Version 01'))
# Keep the original page in the top-level document so it does not depend on framing support.
import re
archive_shell_css='\n'.join(match.group(0) for match in re.finditer(r'([^{}]+)\{([^{}]*)\}',css.split('@media')[0]) if match.group(1).strip().startswith(('.layout','.timeline','.history-toggle','.archive-bar')))
archive_shell_css += '\n@media(max-width:760px){.layout{margin-right:0}.timeline{display:none;width:264px;box-shadow:-10px 0 40px #173a3520}.timeline.open{display:block}.history-toggle{display:block;position:fixed;bottom:20px;right:20px;border:0;border-radius:30px;padding:13px 19px;background:#173a35;color:white;z-index:20}.archive-bar{padding:14px 18px}.archive-bar a{float:none!important;display:block;margin-top:8px}.page{padding-bottom:80px}}'
archive_shell_css += '\n.timeline{color:#173a35;font-family:system-ui,sans-serif;line-height:1.5}.timeline a{color:inherit;font-weight:400}.timeline h2,.timeline h3{font-family:inherit}.timeline-item h3{font-weight:500}.history-toggle:focus-visible,.timeline a:focus-visible{outline:3px solid #dc6945;outline-offset:4px}'
(root/'archive-shell.css').write_text(archive_shell_css)
archive_page=d/'index.html'
archive_html=archive_page.read_text().replace('<link rel="stylesheet" href="/style.css">','<link rel="stylesheet" href="/archive/v1/app.css"><link rel="stylesheet" href="/archive-shell.css">')
archive_html=archive_html.replace('<iframe class="archive" title="Original portfolio, version 1" src="/archive/v1/"></iframe>','<div id="root"></div>')
archive_html=archive_html.replace('</body>','<script src="/archive/v1/app.js"></script></body>')
archive_page.write_text(archive_html)
d=root/'changes/v1-v2';d.mkdir(parents=True,exist_ok=True)
diff=nav+'''<main class="motion"><section class="hero"><div class="eyebrow"><span class="dot"></span>Chapter 01 → 02 / September 30, 2026</div><h1 class="diff-title">Same person.<br>A new <em>perspective.</em></h1><p class="intro">A guided look at how this site evolved. The original remains intact; this chapter explains the choices behind the new version.</p><div class="actions"><a class="button" href="/versions/v2/">Explore version 02 ↗</a><a href="/versions/v1/">Revisit version 01 ↗</a></div></section><section class="section"><div class="section-head"><h2><span class="section-number">01</span>From a list to a story.</h2></div><div class="comparison"><article class="compare-card"><span class="diff-label">Before / V01</span><h3><span class="removed">Software Engineer</span></h3><p>The page led with a role, then listed skills and libraries across separate cards.</p></article><article class="compare-card after"><span class="diff-label">After / V02</span><h3><span class="added">Make it work. Make it matter.</span></h3><p>The introduction now leads with the purpose of the work: turning data and processes into useful tools. The technical foundation is still there.</p></article></div></section><section class="section"><div class="section-head"><h2><span class="section-number">02</span>A different visual language.</h2></div><div class="comparison"><div class="compare-card"><span class="diff-label">Before / soft cards</span><div class="mini-v1">Filipe<div>About me</div><div>Main Programming Skills</div></div></div><div class="compare-card after"><span class="diff-label">After / editorial sections</span><div class="mini-v2">Make it work.<br><span style="color:var(--accent)">Make it matter.</span><hr><small style="font-size:12px">01 / Curiosity, put to work.</small></div></div></div><p>Illustrative excerpts of each visual direction. Open the full versions above to explore the actual pages.</p></section><section class="section"><div class="section-head"><h2><span class="section-number">03</span>What's new.</h2></div><div class="columns"><div><h3>The past becomes part of the site.</h3><p>Each version has its own address. A timeline connects the chapters, and the root always opens the latest one. The previous content and styling are archived separately.</p><h3>A clearer connection to the code.</h3><p>A projects section and a direct source link make the portfolio's own repository easier to find.</p></div><div><h3>Cloud gets its own space.</h3><p>The new page describes an interest in cloud both as a practical tool and as the architecture behind computing at scale.</p><h3>Skills are easier to scan.</h3><p>The detailed lists are condensed into software, data, interfaces and operations. The complete older lists remain available in version 01.</p></div></div></section><section class="section cloud"><h2>A snapshot, not a replacement.</h2><p>The earlier version is a record of a particular moment. This comparison is written for this transition, rather than generated automatically, so changes in structure and meaning can be explained too.</p><a class="button" href="/">Back to the present ↗</a></section></main>'''+footer
(d/'index.html').write_text(shell(diff,'What changed · V01 to V02'))
